import{_ as a,C as c,o as e,c as i,a2 as d,b as l,w as o,a as s,E as u,a3 as n}from"./chunks/framework.BaXgE4DV.js";const p=JSON.parse('{"title":"신고·차단과 자동 숨김","description":"","frontmatter":{},"headers":[],"relativePath":"features/safety.md","filePath":"features/safety.md","lastUpdated":1791456149000}'),h={name:"features/safety.md"};function C(E,t,q,B,b,g){const r=c("Mermaid");return e(),i("div",null,[t[1]||(t[1]=d('<h1 id="신고·차단과-자동-숨김" tabindex="-1">신고·차단과 자동 숨김 <a class="header-anchor" href="#신고·차단과-자동-숨김" aria-label="Permalink to &quot;신고·차단과 자동 숨김&quot;">​</a></h1><p>다른 사람에게 보이는 사용자 콘텐츠(UGC)를 안전하게 유지하는 기능입니다. 스토어 정책(Apple 1.2, Google Play UGC)은 부적절한 콘텐츠 <strong>신고</strong>, 사용자 <strong>차단</strong>, <strong>필터</strong>, 운영자의 <strong>빠른 대응</strong>을 요구합니다. → <a href="/grato-docs/decisions#adr-14">결정 기록 #14</a>, <a href="/grato-docs/operations/compliance#ugc">출시 준비 체크리스트</a></p><table tabindex="0"><thead><tr><th>수단</th><th>누가</th><th>하는 일</th></tr></thead><tbody><tr><td><a href="#report">신고</a></td><td>로그인 사용자 (비로그인은 이메일)</td><td>글·댓글·사용자·Circle을 운영자 대기열에 올림</td></tr><tr><td><a href="#block">차단</a></td><td>로그인 사용자</td><td>그 사람의 글·댓글과 그 사람 때문에 오는 알림을 내 화면에서 없앰</td></tr><tr><td><a href="#auto-moderation">자동 숨김</a></td><td>서버</td><td>욕설·혐오 표현이 든 공유 글·댓글을 바로 숨기고 대기열에 올림</td></tr><tr><td><a href="#moderate">운영자 처리</a></td><td>운영자 (<code>users.isAdmin</code>)</td><td>숨기기·숨김 해제·삭제·이용 정지·문제 없음</td></tr></tbody></table><h2 id="scope" tabindex="-1">대상: 다른 사람에게 보이는 것 <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;대상: 다른 사람에게 보이는 것 {#scope}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>콘텐츠</th><th>보는 사람</th><th>신고</th><th>자동 검사</th></tr></thead><tbody><tr><td>Circle에 공유한 감사 글</td><td>Circle 멤버</td><td>✅</td><td>작성할 때</td></tr><tr><td>링크로 공개한 감사 글</td><td>링크가 있는 누구나</td><td>비로그인은 이메일</td><td>공개로 바꿀 때</td></tr><tr><td>Circle 글의 댓글</td><td>Circle 멤버</td><td>✅</td><td>작성할 때</td></tr><tr><td>공개 이름 (<code>이름 #태그</code>)</td><td>Circle 멤버, 댓글·공유 페이지 방문자</td><td>멤버 신고</td><td>바꿀 때 (숨기지 않고 대기열에만)</td></tr><tr><td>Circle 이름·설명</td><td>멤버, 초대 링크 방문자</td><td>Circle 신고</td><td>만들 때 거절, 바꿀 때 대기열</td></tr><tr><td>선정된 제안 질문</td><td>로그인 사용자</td><td>운영자 질문 탭</td><td>제출할 때 + 사전 검토 → <a href="/grato-docs/features/questions">질문 제안과 선정</a></td></tr></tbody></table><p><strong>&quot;나만 보기&quot; 글은 대상이 아닙니다.</strong> 다른 사람이 볼 수 없으니 신고할 수도 없고, 자동 검사도 하지 않으며, 운영자도 그 내용을 볼 수 없습니다(규칙이 막음). 개인 일기를 운영자 앞에 내놓지 않기 위해서입니다.</p><h2 id="report" tabindex="-1">신고 <a class="header-anchor" href="#report" aria-label="Permalink to &quot;신고 {#report}&quot;">​</a></h2><h3 id="어디서" tabindex="-1">어디서 <a class="header-anchor" href="#어디서" aria-label="Permalink to &quot;어디서&quot;">​</a></h3><table tabindex="0"><thead><tr><th>위치</th><th>대상</th></tr></thead><tbody><tr><td>글 카드·글 상세의 &quot;⋯&quot; 메뉴 (<code>SafetyMenu</code>)</td><td>감사 글 (<code>gratitude</code>)</td></tr><tr><td>댓글의 &quot;⋯&quot; 메뉴</td><td>댓글 (<code>comment</code>, 부모 글 ID 포함)</td></tr><tr><td>Circle 설정 › 멤버의 &quot;⋯&quot; 메뉴 (&quot;이 멤버 신고하기&quot;)</td><td>사용자 (<code>user</code>)</td></tr><tr><td>Circle 설정 › &quot;Circle 신고하기&quot; (관리자가 아닌 멤버)</td><td>Circle (<code>circle</code>)</td></tr><tr><td>공개 공유 페이지 하단 &quot;신고하기&quot; (<code>ShareReportLink</code>)</td><td>로그인 없이 고객지원 이메일로 (페이지 주소가 채워진 메일 작성 화면)</td></tr></tbody></table><p>메뉴는 자기 콘텐츠에는 &quot;삭제하기&quot;만, 다른 사람의 콘텐츠에는 &quot;신고하기&quot;와 &quot;차단하기&quot;를 보여 줍니다(내 글에 달린 다른 사람의 댓글은 삭제도 가능).</p><h3 id="신고-화면-reportsheet" tabindex="-1">신고 화면 (<code>ReportSheet</code>) <a class="header-anchor" href="#신고-화면-reportsheet" aria-label="Permalink to &quot;신고 화면 (`ReportSheet`)&quot;">​</a></h3><ul><li>사유(필수, 하나): 스팸·광고, 욕설·괴롭힘, 음란·성적인 내용, 혐오·차별 표현, 자해·자살 관련 내용, 개인정보 노출, 기타</li><li>자세한 내용(선택, 500자까지)</li><li>보낸 뒤 작성자를 <strong>차단할지</strong> 바로 묻습니다.</li><li>신고는 <code>reports</code>에 <code>addDoc</code>(자동 ID)으로 만들고, 보낸 사람도 다시 읽을 수 없습니다. 신고한 사람이 누구인지는 상대에게 알리지 않습니다.</li></ul><h3 id="report-trigger" tabindex="-1">서버 처리 (<code>onReportCreated</code>) <a class="header-anchor" href="#report-trigger" aria-label="Permalink to &quot;서버 처리 (`onReportCreated`) {#report-trigger}&quot;">​</a></h3>',13)),(e(),l(n,null,{default:o(()=>[u(r,{id:"mermaid-268",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22reports%2F%7Bid%7D%20%EC%83%9D%EC%84%B1%22%5D%20--%3E%20F%7B%2224%EC%8B%9C%EA%B0%84%20%EC%95%88%EC%97%90%20%EC%9D%B4%20%EC%82%AC%EC%9A%A9%EC%9E%90%EA%B0%80%3Cbr%2F%3E%EB%B3%B4%EB%82%B8%20%EC%8B%A0%EA%B3%A0%EA%B0%80%2020%EA%B0%9C%20%EB%84%98%EC%9D%8C%3F%22%7D%0A%20%20F%20--%20%EC%98%88%20--%3E%20S%5B%22status%3A%20spam%3Cbr%2F%3E(%EC%95%8C%EB%A6%BC%20%EC%97%86%EC%9D%8C)%22%5D%0A%20%20F%20--%20%EC%95%84%EB%8B%88%EC%98%A4%20--%3E%20D%5B%22%EB%8C%80%EC%83%81%20%EC%9E%91%EC%84%B1%EC%9E%90%20%C2%B7%20200%EC%9E%90%20%EB%B0%9C%EC%B7%8C%EB%A5%BC%3Cbr%2F%3E%EC%8B%A0%EA%B3%A0%EC%97%90%20%EB%B3%B5%EC%82%AC%22%5D%0A%20%20D%20--%3E%20B%7B%22%EC%B0%A8%EB%8B%A8%EC%9C%BC%EB%A1%9C%20%EC%83%9D%EA%B8%B4%20%EC%8B%A0%EA%B3%A0%3F%22%7D%0A%20%20B%20--%20%EC%98%88%20--%3E%20Q%5B%22%EB%8C%80%EA%B8%B0%EC%97%B4%EC%97%90%EB%A7%8C%22%5D%0A%20%20B%20--%20%EC%95%84%EB%8B%88%EC%98%A4%20--%3E%20FIRST%7B%22%EC%9D%B4%20%EB%8C%80%EC%83%81%EC%9D%98%20%EC%B2%AB%20%EC%97%B4%EB%A6%B0%20%EC%8B%A0%EA%B3%A0%3F%22%7D%0A%20%20FIRST%20--%20%EC%95%84%EB%8B%88%EC%98%A4%20--%3E%20Q%0A%20%20FIRST%20--%20%EC%98%88%20--%3E%20P%5B%22%EC%9A%B4%EC%98%81%EC%9E%90%20%EC%A0%84%EC%9B%90%EC%97%90%EA%B2%8C%20%ED%91%B8%EC%8B%9C%3Cbr%2F%3E'%EC%83%88%20%EC%8B%A0%EA%B3%A0%EA%B0%80%20%EC%A0%91%EC%88%98%EB%90%90%EC%96%B4%EC%9A%94'%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<ul><li><strong>도배 방지</strong>: 규칙은 개수를 셀 수 없어, 한 사용자가 24시간에 보낸 21번째 신고부터 <code>spam</code>으로 표시합니다(차단으로 생긴 신고 포함). 스팸 신고도 운영자 화면의 &quot;스팸 의심&quot; 탭에서 볼 수 있습니다.</li><li><strong>대상 정보 복사</strong>: 작성자(<code>targetOwnerId</code>)와 내용 발췌(<code>targetPreview</code>, 200자)를 신고에 남겨, 작성자가 글을 지운 뒤에도 운영자가 판단하고 이용 정지할 수 있게 합니다. &quot;나만 보기&quot; 글은 발췌를 남기지 않습니다.</li><li><strong>푸시</strong>: 약관이 &quot;24시간 안에 검토&quot;를 약속하므로 운영자 기기로 바로 알립니다. 같은 대상에 이미 열린 신고가 있으면 다시 보내지 않고 같은 카드에 모입니다. 잠금 화면에 보이므로 내용과 이름은 넣지 않고 종류와 사유만 씁니다(예: &quot;감사 글 · 욕설·괴롭힘. 24시간 안에 확인해주세요&quot;). 클릭하면 <code>/admin?tab=reports</code>.</li></ul><h2 id="block" tabindex="-1">차단 <a class="header-anchor" href="#block" aria-label="Permalink to &quot;차단 {#block}&quot;">​</a></h2><p><code>users/{uid}/blocks/{차단한 uid}</code> = <code>{ createdAt }</code>. 본인만 읽고 씁니다.</p><table tabindex="0"><thead><tr><th>효과</th><th>방식</th></tr></thead><tbody><tr><td>그 사람의 글·댓글이 내 화면에서 빠짐</td><td>클라이언트가 그릴 때 거름(<code>canSeeItem</code>). 다시 불러오지 않아도 차단·해제가 바로 반영됨</td></tr><tr><td>그 사람 때문에 오는 알림이 오지 않음</td><td>Circle 새 글 알림은 작성자를 차단한 멤버를 빼고, 리액션 알림은 글 작성자가 차단한 사람의 리액션이면 보내지 않음</td></tr><tr><td>운영자가 알게 됨</td><td><code>onBlockCreated</code>가 낮은 우선순위 신고(<code>source: &quot;block&quot;</code>, 푸시 없음)를 남김. 한 쌍에 한 번만</td></tr><tr><td>상대는 모름</td><td>상대에게 알리지 않고, 상대 화면은 바뀌지 않음</td></tr></tbody></table><ul><li>차단한 화면에서는 그 자리에 &quot;차단한 사용자의 글이에요&quot; 안내를 남겨, 열려 있던 메뉴나 신고 화면이 갑자기 사라지지 않게 합니다.</li><li>차단 목록과 해제: MyPage › 설정 › <strong>차단한 사용자</strong> (<code>/settings/blocked</code>). Circle 설정의 멤버 목록에도 &quot;차단됨&quot;이 표시됩니다.</li><li>차단은 <strong>내가 보는 것</strong>을 정리하는 기능입니다. Circle 멤버십은 바뀌지 않으므로, 같은 Circle에 있는 상대는 내가 공유한 글을 계속 볼 수 있습니다. 완전히 떨어지려면 Circle 관리자가 <a href="/grato-docs/features/circles">내보내기</a>를 합니다.</li><li>차단 목록은 첫 화면을 그린 뒤 필요한 컴포넌트가 처음 물을 때 한 번 구독합니다(시작을 막지 않음, <a href="/grato-docs/decisions#adr-13">ADR-13</a>).</li></ul><h2 id="auto-moderation" tabindex="-1">자동 숨김 <a class="header-anchor" href="#auto-moderation" aria-label="Permalink to &quot;자동 숨김 {#auto-moderation}&quot;">​</a></h2><p>다른 사람이 볼 수 있는 글·댓글의 텍스트가 <a href="/grato-docs/architecture/cloud-functions#content-filter">내용 필터</a>의 <strong>욕설·혐오 표현</strong>에 걸리면 서버가 바로 숨기고 운영자 대기열에 올립니다.</p><table tabindex="0"><thead><tr><th>언제</th><th>트리거</th></tr></thead><tbody><tr><td>Circle에 공유한 글을 만들 때</td><td><code>onGratitudeCreated</code> (통계·배지·알림보다 먼저)</td></tr><tr><td>글을 링크 공개로 바꿀 때</td><td><code>onReactionUpdated</code> (<code>isPublic</code> false → true)</td></tr><tr><td>Circle 글에 댓글을 달 때</td><td><code>onCommentCreated</code></td></tr></tbody></table><ul><li>연락처와 링크는 숨기지 않습니다. 친구에게 쓰는 글에 링크가 들어가는 것은 자연스럽기 때문입니다(질문 제안 필터와 다른 점). 그런 경우는 신고로 다룹니다.</li><li>숨기면 글·댓글에 <code>moderation = { status: &quot;hidden&quot;, source: &quot;auto&quot;, reason: &quot;profanity&quot; }</code>를 쓰고, 같은 트랜잭션에서 시스템 신고(<code>reporterId: &quot;system&quot;</code>)를 만듭니다. 같은 대상에는 한 번만 만듭니다.</li><li><strong>숨긴 Circle 글은 Circle에서 빠집니다.</strong> <code>groupId</code>를 비우고 원래 Circle은 <code>moderation.groupId</code>에 둬서 Circle 피드 쿼리에 나오지 않게 하고, 숨김을 해제하면 되돌립니다. 작성자의 &quot;내 기록&quot;에는 그대로 있습니다.</li><li>숨긴 글은 Circle 새 글 알림을 보내지 않고, 공유 페이지는 &quot;비공개&quot;로 보여 줍니다(검토 중이라는 사실도 드러내지 않음). 숨긴 글은 다시 링크 공개로 바꿀 수 없습니다.</li><li>운영자가 이미 결정한 콘텐츠(<code>moderation</code> 기록이 있음)는 필터가 다시 건드리지 않습니다. 운영자가 되살린 글이 다시 숨겨지지 않습니다.</li></ul><h3 id="작성자와-다른-사람에게-보이는-것" tabindex="-1">작성자와 다른 사람에게 보이는 것 <a class="header-anchor" href="#작성자와-다른-사람에게-보이는-것" aria-label="Permalink to &quot;작성자와 다른 사람에게 보이는 것&quot;">​</a></h3><table tabindex="0"><thead><tr><th>보는 사람</th><th>숨긴 글·댓글</th></tr></thead><tbody><tr><td>작성자</td><td>그대로 보이고 &quot;검토 중이에요&quot; 표시. 글 상세에 &quot;신고나 자동 검토로 지금은 다른 사람에게 보이지 않아요&quot; 안내</td></tr><tr><td>운영자</td><td>&quot;숨김 처리됨&quot; 표시와 함께 보임</td></tr><tr><td>그 밖의 사람</td><td>보이지 않음 (피드, 댓글 목록, 글 상세 모두)</td></tr></tbody></table><h3 id="이름" tabindex="-1">이름 <a class="header-anchor" href="#이름" aria-label="Permalink to &quot;이름&quot;">​</a></h3><p>공개 이름과 Circle 이름·설명은 클라이언트가 쓰므로 필터를 쓴 뒤에 검사합니다(<code>onPublicNameWritten</code>, <code>onCircleNameWritten</code>). 이름은 <strong>바꾸지 않고</strong> 시스템 신고만 남깁니다. 같은 이름에는 한 번, 다시 바꾼 이름에는 다시 남깁니다. 운영자는 &quot;문제 없음&quot;으로 닫거나 계정을 이용 정지합니다. Circle을 <strong>만들 때</strong>는 <code>createCircle</code>이 이런 이름을 처음부터 거절합니다(&quot;Circle 이름이나 설명에 쓸 수 없는 표현이 있어요&quot;).</p><h2 id="moderate" tabindex="-1">운영자 처리 <a class="header-anchor" href="#moderate" aria-label="Permalink to &quot;운영자 처리 {#moderate}&quot;">​</a></h2><p>관리자 페이지의 첫 탭이 <strong>신고</strong>입니다(<code>/admin?tab=reports</code>, <code>ReportManager</code>). 이 화면 코드는 관리자 페이지에서만 받습니다.</p><ul><li>&quot;처리 대기&quot;와 &quot;스팸 의심&quot; 탭, 탭마다 개수. 최신순 100개.</li><li>카드마다 신고 종류·사유·자세한 내용·시각, 그리고 <strong>대상 미리보기</strong>(지금 내용). 대상이 지워졌으면 신고 당시 발췌를 보여 줍니다. &quot;나만 보기&quot; 글은 운영자도 읽을 수 없어 &quot;볼 수 없음&quot;으로 표시됩니다.</li><li>처리는 <code>moderate</code> callable 하나로 합니다. → <a href="/grato-docs/architecture/cloud-functions#moderate">Cloud Functions</a></li></ul><table tabindex="0"><thead><tr><th>작업</th><th>화면 이름</th><th>가능한 대상</th><th>결과</th></tr></thead><tbody><tr><td><code>hide</code></td><td>숨기기</td><td>글, 댓글, 질문</td><td>글·댓글: <code>moderation.status = &quot;hidden&quot;</code>(<code>source: &quot;admin&quot;</code>). 질문: 선정됨 → 숨김</td></tr><tr><td><code>unhide</code></td><td>숨김 해제</td><td>글, 댓글</td><td><code>moderation.status = &quot;visible&quot;</code>, 글은 Circle로 돌아감</td></tr><tr><td><code>delete</code></td><td>삭제</td><td>글, 댓글, 질문, Circle</td><td>문서 삭제. 글은 <a href="/grato-docs/architecture/cloud-functions#gratitude-deleted">삭제 트리거</a>가 댓글·통계를 정리. Circle은 <code>deleteCircle</code>과 같은 정리(글은 보존)</td></tr><tr><td><code>disableUser</code></td><td>이용 정지</td><td>모든 대상의 작성자 (Circle은 관리자)</td><td>로그인 차단·세션 철회·남은 토큰 잠금. 운영자 계정과 자기 자신은 불가</td></tr><tr><td><code>dismiss</code></td><td>문제 없음</td><td>모두</td><td>대상은 그대로</td></tr></tbody></table><ul><li>처리하면 <strong>같은 대상의 열린 신고가 모두</strong> 닫힙니다(<code>resolved</code>, &quot;문제 없음&quot;은 <code>dismissed</code>). 닫힌 신고는 1년 뒤 TTL로 지워집니다(처리방침의 보관 기간).</li><li>작업마다 <code>adminAuditLogs</code>에 <code>moderate_&lt;작업&gt;</code>을 같은 커밋으로 남깁니다. 처리한 운영자는 신고 문서가 아니라 여기에만 남습니다.</li><li>질문을 다시 보이게 하려면 관리자 페이지 &quot;질문&quot; 탭에서 다시 선정합니다.</li><li>이용 정지를 푸는 기능은 앱에 없습니다. 이의 신청이 받아들여지면 콘솔에서 사용자를 다시 사용 설정합니다(약관 제12조의 이의 신청 절차).</li></ul><h2 id="데이터와-규칙" tabindex="-1">데이터와 규칙 <a class="header-anchor" href="#데이터와-규칙" aria-label="Permalink to &quot;데이터와 규칙&quot;">​</a></h2><ul><li>데이터: <a href="/grato-docs/architecture/data-model#reports"><code>reports</code></a>, <a href="/grato-docs/architecture/data-model#blocks"><code>users/{uid}/blocks</code></a>, <a href="/grato-docs/architecture/data-model#moderation"><code>moderation</code> 필드</a>, <a href="/grato-docs/architecture/data-model#disabled-users"><code>disabledUsers</code></a></li><li>규칙: <a href="/grato-docs/architecture/security-rules#safety">신고·차단·숨김</a></li><li>함수: <a href="/grato-docs/architecture/cloud-functions#safety">신고와 운영자 처리</a></li></ul>',20))])}const A=a(h,[["render",C]]);export{p as __pageData,A as default};
